    public static void testThreeSegmentsOfAReceiptRowAreOneLineWithThreeWords() {
        emon.Port.Cells lines = emon.Port.newCells();
        emon.Port.Cells words = emon.Port.newCells();
        emon.Port.Cells runs = emon.Port.newCells();
        rtRuns(runs, 1);
        rtSeg(lines, words, 1000, 5000, 1000, 1500, 0);
        rtSeg(lines, words, 8000, 9500, 1010, 1510, 6);
        rtSeg(lines, words, 6500, 6900, 1005, 1500, 3);
        emon.Testport.assertEq(rtRun(lines, words, runs, emon.Port.newCells(), 3), 1, "name, quantity and price are one row, whatever order the detector emitted them in");
        emon.Testport.assertEq(Evidence.lnCount(lines), 1, "one line row remains");
        emon.Testport.assertEq(Evidence.wdCount(words), 3, "the three words are kept");
        emon.Testport.assertEq(Evidence.lnGet(lines, 0, Evidence.lhFirst()), 0, "the line's words start at the range's first word");
        emon.Testport.assertEq(Evidence.lnGet(lines, 0, Evidence.lhCount()), 3, "three words");
        emon.Testport.assertEq(Evidence.wdGet(words, 0, Evidence.hdTstart()), 0, "the name comes first");
        emon.Testport.assertEq(Evidence.wdGet(words, 1, Evidence.hdTstart()), 3, "then the quantity");
        emon.Testport.assertEq(Evidence.wdGet(words, 2, Evidence.hdTstart()), 6, "then the price, in reading order and not in the detector's");
        emon.Testport.assertEq(Evidence.wdGet(words, 0, Evidence.hdLine()), 0, "every word names the one line");
        emon.Testport.assertEq(Evidence.wdGet(words, 2, Evidence.hdLine()), 0, "every word names the one line");
        emon.Testport.assertEq(Evidence.lnGet(lines, 0, Evidence.lhX0()), 1000, "the line's box is the segments' union: left");
        emon.Testport.assertEq(Evidence.lnGet(lines, 0, Evidence.lhX1()), 9500, "right");
        emon.Testport.assertEq(Evidence.lnGet(lines, 0, Evidence.lhY0()), 1000, "top");
        emon.Testport.assertEq(Evidence.lnGet(lines, 0, Evidence.lhY1()), 1510, "bottom");
        emon.Testport.assertEq(Evidence.wdGet(words, 0, Evidence.wfGap()), 1500, "the gap after the name is the distance to the quantity");
        emon.Testport.assertEq(Evidence.wdGet(words, 1, Evidence.wfGap()), 1100, "and after the quantity the distance to the price");
        emon.Testport.assertEq(Evidence.wdGet(words, 2, Evidence.wfGap()), -1, "none after the last");
    }
